import { useEffect, useState } from "react";
import type { SignedInUser, GitHubAppStatus } from "@/lib/dashboard/types";

export function useAuth({ setNotice }: { setNotice: (message: string) => void }) {
  const [signedInUser, setSignedInUser] = useState<SignedInUser | null>(null);
  const [githubAppStatus, setGithubAppStatus] = useState<GitHubAppStatus | null>(null);
  const [githubAppStatusLoading, setGithubAppStatusLoading] = useState(false);
  const [authLoading, setAuthLoading] = useState(true);
  /** "app": sign-in through the GitHub App, which only sees repositories where it is installed. */
  const [githubAccess, setGithubAccess] = useState<"app" | "oauth">("oauth");

  useEffect(() => {
    let cancelled = false;
    fetch("/api/auth/session", { cache: "no-store" })
      .then(async (response) => {
        if (!response.ok) throw new Error("Could not check sign-in status.");
        return response.json() as Promise<{ authenticated: boolean; user: SignedInUser | null; githubAccess?: "app" | "oauth" }>;
      })
      .then((data) => {
        if (cancelled) return;
        setSignedInUser(data.authenticated ? data.user : null);
        setGithubAccess(data.githubAccess === "app" ? "app" : "oauth");
      })
      .catch(() => { if (!cancelled) setSignedInUser(null); })
      .finally(() => { if (!cancelled) setAuthLoading(false); });
    const authResult = new URLSearchParams(window.location.search).get("auth");
    if (authResult === "success") setNotice("Signed in with GitHub. Your saved projects are loading.");
    if (authResult === "error") setNotice("GitHub sign-in could not be completed. Check OAuth configuration and try again.");
    if (authResult === "denied") setNotice("This DEPLO instance is private. Ask its owner to add your GitHub account.");
    const appResult = new URLSearchParams(window.location.search).get("github_app");
    if (appResult === "connected") setNotice("GitHub App connected. Private repository push deployments are enabled for repositories selected in the installation.");
    if (appResult === "error") setNotice("GitHub App installation could not be linked. Check the app setup URL, private key, and database migration.");
    if (appResult === "cancelled") setNotice("GitHub App installation was cancelled.");
    if (appResult === "signin_required") setNotice("Sign in with GitHub before installing the DEPLO GitHub App.");
    if (authResult || appResult) window.history.replaceState({}, "", window.location.pathname);
    return () => { cancelled = true; };
  }, []);

  useEffect(() => {
    if (!signedInUser) {
      setGithubAppStatus(null);
      setGithubAppStatusLoading(false);
      return;
    }
    let cancelled = false;
    setGithubAppStatusLoading(true);
    fetch("/api/auth/github/app-status", { cache: "no-store" })
      .then(async (response) => {
        const data = await response.json() as GitHubAppStatus & { error?: string };
        if (!response.ok) throw new Error(data.error || "Could not load GitHub App status.");
        return data;
      })
      .then((data) => { if (!cancelled) setGithubAppStatus(data); })
      .catch(() => { if (!cancelled) setGithubAppStatus(null); })
      .finally(() => { if (!cancelled) setGithubAppStatusLoading(false); });
    return () => { cancelled = true; };
  }, [signedInUser]);

  return {
    signedInUser,
    setSignedInUser,
    githubAppStatus,
    setGithubAppStatus,
    githubAppStatusLoading,
    authLoading,
    githubAccess,
  };
}

import { readFileSync } from "node:fs";
import { join } from "node:path";

/**
 * Loads the Rust BLAKE3 hasher (native/blake3-wasm, built to
 * lib/deploy/blake3.wasm). Returns null when the file is missing or cannot be
 * instantiated, so callers fall back to the JavaScript implementation in
 * ./blake3 and hashes are identical either way.
 */
export type WasmHasher = {
  hash(input: Uint8Array): Uint8Array;
  /** BLAKE3(base64(content) + extension), the Cloudflare Pages asset key before truncation. */
  pagesAssetHash(content: Uint8Array, extension: string): Uint8Array;
};

type Exports = {
  memory: WebAssembly.Memory;
  alloc(len: number): number;
  dealloc(ptr: number, len: number): void;
  hash(input: number, len: number, out: number): void;
  pages_asset_hash(content: number, contentLen: number, extension: number, extensionLen: number, out: number): void;
};

export const DEFAULT_WASM_PATH = join(process.cwd(), "lib", "deploy", "blake3.wasm");

let cached: WasmHasher | null | undefined;

/** The shared hasher, loaded once per process. */
export function wasmHasher(env: Record<string, string | undefined> = process.env): WasmHasher | null {
  if (cached === undefined) cached = env.DEPLO_DISABLE_WASM_HASH === "1" ? null : loadWasmHasher(DEFAULT_WASM_PATH);
  return cached;
}

export function loadWasmHasher(path: string): WasmHasher | null {
  let exports: Exports;
  try {
    const module = new WebAssembly.Module(readFileSync(path));
    exports = new WebAssembly.Instance(module, {}).exports as unknown as Exports;
    if (!(exports.memory instanceof WebAssembly.Memory) || typeof exports.alloc !== "function" || typeof exports.pages_asset_hash !== "function") return null;
  } catch {
    return null;
  }

  // Copies `bytes` into wasm memory; the caller frees the returned pointer.
  const put = (bytes: Uint8Array): number => {
    const ptr = exports.alloc(bytes.length);
    if (!ptr) throw new Error("BLAKE3 wasm allocation failed.");
    // Read memory.buffer after alloc: growing memory replaces the buffer.
    new Uint8Array(exports.memory.buffer, ptr, bytes.length).set(bytes);
    return ptr;
  };
  const withOutput = (run: (out: number) => void): Uint8Array => {
    const out = exports.alloc(32);
    if (!out) throw new Error("BLAKE3 wasm allocation failed.");
    try {
      run(out);
      return new Uint8Array(exports.memory.buffer, out, 32).slice();
    } finally {
      exports.dealloc(out, 32);
    }
  };

  const hasher: WasmHasher = {
    hash(input) {
      const ptr = put(input);
      try { return withOutput((out) => exports.hash(ptr, input.length, out)); } finally { exports.dealloc(ptr, input.length); }
    },
    pagesAssetHash(content, extension) {
      const ext = new TextEncoder().encode(extension);
      const contentPtr = put(content);
      try {
        const extPtr = put(ext);
        try {
          return withOutput((out) => exports.pages_asset_hash(contentPtr, content.length, extPtr, ext.length, out));
        } finally { exports.dealloc(extPtr, ext.length); }
      } finally { exports.dealloc(contentPtr, content.length); }
    },
  };

  // Refuse a build that disagrees with the published BLAKE3 vector for "".
  try {
    const empty = Buffer.from(hasher.hash(new Uint8Array(0))).toString("hex");
    if (empty !== "af1349b9f5f9a1a6a0404dea36dcc9499bcb25c9adc112b7cc9a93cae41f3262") return null;
  } catch {
    return null;
  }
  return hasher;
}

import { createWriteStream } from "node:fs";
import { mkdir, rm } from "node:fs/promises";
import { dirname, isAbsolute, join, relative, resolve, sep } from "node:path";
import { Transform } from "node:stream";
import { pipeline } from "node:stream/promises";
import * as yauzl from "yauzl";
import {
  MAX_ARCHIVE_EXPANDED_BYTES,
  validateArchiveEntryPath,
  validateArchiveMetadata,
} from "@/lib/uploads/archive-policy";

export type ExtractionResult = {
  fileCount: number;
  totalBytes: number;
};

function assertSafeEntryType(entry: yauzl.Entry): void {
  const unixMode = (entry.externalFileAttributes >>> 16) & 0xffff;
  const fileType = unixMode & 0o170000;
  const allowedTypes = new Set([0, 0o100000, 0o040000]);

  if (!allowedTypes.has(fileType)) {
    throw new Error("ZIP archives cannot contain symbolic links or special files.");
  }
}

function resolveEntryPath(root: string, archivePath: string): string {
  const segments = archivePath.endsWith("/") ? archivePath.slice(0, -1).split("/") : archivePath.split("/");
  const destination = resolve(root, ...segments);
  const relativePath = relative(root, destination);

  if (!relativePath || relativePath === ".." || relativePath.startsWith(".." + sep) || isAbsolute(relativePath)) {
    throw new Error("Archive entry resolves outside the extraction directory.");
  }

  return destination;
}

export async function extractZipSafely(
  archivePath: string,
  destinationRoot: string,
): Promise<ExtractionResult> {
  const zipFile = await yauzl.openPromise(archivePath, {
    autoClose: false,
    validateEntrySizes: true,
    strictFileNames: true,
  });
  let destinationCreated = false;

  try {
    const entries: yauzl.Entry[] = [];
    for await (const entry of zipFile.eachEntry()) {
      entries.push(entry);
    }

    const metadataError = validateArchiveMetadata(entries.map((entry) => ({
      path: entry.fileName,
      compressedSize: entry.compressedSize,
      uncompressedSize: entry.uncompressedSize,
    })));
    if (metadataError) throw new Error(metadataError);

    const seenPaths = new Set<string>();
    for (const entry of entries) {
      assertSafeEntryType(entry);
      const pathError = validateArchiveEntryPath(entry.fileName);
      if (pathError) throw new Error(pathError);
      const normalized = entry.fileName.replace(/\/$/, "").toLowerCase();
      if (seenPaths.has(normalized)) throw new Error("ZIP archives cannot contain duplicate paths.");
      seenPaths.add(normalized);
    }

    await mkdir(destinationRoot, { recursive: false, mode: 0o700 });
    destinationCreated = true;

    let totalBytes = 0;
    let fileCount = 0;

    for (const entry of entries) {
      const isDirectory = entry.fileName.endsWith("/") ||
        (((entry.externalFileAttributes >>> 16) & 0xffff) & 0o170000) === 0o040000;
      const destination = resolveEntryPath(destinationRoot, entry.fileName);

      if (isDirectory) {
        await mkdir(destination, { recursive: true, mode: 0o700 });
        continue;
      }

      await mkdir(dirname(destination), { recursive: true, mode: 0o700 });
      let entryBytes = 0;
      const meter = new Transform({
        transform(chunk: Buffer, _encoding, callback) {
          entryBytes += chunk.length;
          totalBytes += chunk.length;
          if (entryBytes > entry.uncompressedSize || totalBytes > MAX_ARCHIVE_EXPANDED_BYTES) {
            callback(new Error("Extracted archive data exceeded its declared or configured size limit."));
            return;
          }
          callback(null, chunk);
        },
      });

      const input = await zipFile.openReadStreamPromise(entry);
      await pipeline(
        input,
        meter,
        // Keep only the executable bit (for build scripts); never setuid, group or world bits.
        createWriteStream(destination, { flags: "wx", mode: (((entry.externalFileAttributes >>> 16) & 0o111) !== 0) ? 0o700 : 0o600 }),
      );

      if (entryBytes !== entry.uncompressedSize) {
        throw new Error("An archive entry did not match its declared uncompressed size.");
      }
      fileCount += 1;
    }

    return { fileCount, totalBytes };
  } catch (error) {
    if (destinationCreated) {
      await rm(destinationRoot, { recursive: true, force: true }).catch(() => undefined);
    }
    throw error;
  } finally {
    zipFile.close();
  }
}

import test from "node:test";
import assert from "node:assert/strict";
import { mkdtemp, readFile, readdir, rm, utimes } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import * as yazl from "yazl";
import { createRunnerServer, validateRunnerBindHost } from "../../services/build-runner/src/server";

const token = "runner-secret-".padEnd(40, "x");
const jobId = "00000000-0000-4000-8000-000000000001";
function makeZip(items: { name: string; content: Buffer; mode?: number }[] = [
  { name: "index.html", content: Buffer.from("<!doctype html><html></html>") },
]): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const zip = new yazl.ZipFile();
    const chunks: Buffer[] = [];
    zip.outputStream.on("data", (chunk: Buffer) => chunks.push(chunk));
    zip.outputStream.on("error", reject);
    zip.outputStream.on("end", () => resolve(Buffer.concat(chunks)));
    for (const item of items) zip.addBuffer(item.content, item.name, { compress: true, ...(item.mode ? { mode: item.mode } : {}) });
    zip.end();
  });
}
async function setup(t: test.TestContext) {
  const dir = await mkdtemp(join(tmpdir(), "deplo-runner-"));
  const server = createRunnerServer({ token, dataDir: dir, hostPreflight: { platform: "linux", kvmDevicePath: join(dir, "missing-kvm"), firecrackerBinaryPath: join(dir, "missing-firecracker"), kernelImagePath: join(dir, "missing-kernel"), initrdPath: join(dir, "missing-initrd"), cgroupControllersPath: join(dir, "missing-controllers") } });
  await new Promise<void>(resolve => server.listen(0, "127.0.0.1", resolve));
  const address = server.address();
  if (!address || typeof address === "string") throw new Error("No test server address.");
  t.after(async () => { await new Promise<void>(resolve => server.close(() => resolve())); await rm(dir, { recursive: true, force: true }); });
  return { dir, base: "http://127.0.0.1:" + address.port };
}
function form(bytes: Uint8Array, metadata = { repositoryFullName: "octocat/hello-world", sourceCommitSha: "a".repeat(40) }) {
  const data = new FormData();
  data.set("metadata", JSON.stringify(metadata));
  const copy = new Uint8Array(bytes.byteLength);
  copy.set(bytes);
  data.set("archive", new Blob([copy.buffer as ArrayBuffer], { type: "application/zip" }), "source.zip");
  return data;
}

test("health endpoint reports runner readiness without enabling builds", async t => {
  const archive = await makeZip();
  const { base } = await setup(t);
